// 完全可编译的一个程序：入口 + 泛型 + struct + enum + match + 闭包 + defer
import vec;

type Shape = enum {
    Circle(i32),     // 半径
    Rect(i32),       // 面积（变体只带一个 payload —— 见附录 B）
    Empty,
}

type Point = struct {
    x: i32,
    y: i32,
}

fn area(s: Shape) -> i32 {
    match s {
        Shape::Circle(r) => 3 * r * r,
        Shape::Rect(a) => a,
        Shape::Empty => 0,
    }
}

fn max<T>(a: T, b: T) -> T {
    if a > b { return a; }
    return b;
}

fn cleanup() -> i32 {
    return 0;
}

fn main_jhyy() -> i32 {
    defer cleanup();

    let p = Point { x: 3, y: 4 };
    let s = Shape::Rect(p.x * p.y);
    let a = area(s);

    let f = |n: i32| { n * 2 };
    let d = f(a);

    let m: i32 = max::<i32>(d, 100);

    return m;   // 100
}
